package ro.leo.visual;
import android.content.*;import android.os.Bundle;import java.util.*;
public final class QuickHomeActivity extends LeoActivity {
 protected void onCreate(Bundle b){super.onCreate(b);home();}
 private void home(){list("Acces rapid",Arrays.asList("★ Aplicații favorite","◷ Aplicații Leo recente","Editează favoritele","Configurează scurtăturile Home","Configurări rapide","Notificări","Ajutor Leo"),0,new Choice(){public void pick(int n){if(n<2)apps(n==0?"favorites":"recent");else if(n==2)choose();else if(n==3)slots();else startActivity(new Intent(QuickHomeActivity.this,n==4?QuickSettingsActivity.class:n==5?NotificationsActivity.class:HelpActivity.class));}},"",null);}
 private void apps(final String key){final ArrayList<Integer> ids=HomeAccess.get(this,key);ArrayList<String> labels=new ArrayList<String>();for(int id:ids)labels.add(AppCatalog.NAMES[id]);list(key.equals("favorites")?"Favorite Home":"Recente în Leo",labels,0,new Choice(){public void pick(int n){HomeAccess.open(QuickHomeActivity.this,ids.get(n));finish();}},"",null);back=new Runnable(){public void run(){home();}};}
 private void choose(){final ArrayList<Integer> favorite=HomeAccess.get(this,"favorites");ArrayList<String> labels=new ArrayList<String>();for(int i=0;i<AppCatalog.NAMES.length;i++)labels.add((favorite.contains(i)?"★ ":"☆ ")+AppCatalog.NAMES[i]);list("Favorite · maximum 12",labels,0,new Choice(){public void pick(int n){if(favorite.contains(n))favorite.remove((Integer)n);else if(favorite.size()<12)favorite.add(n);else{notice("Maximum 12 favorite");return;}HomeAccess.save(QuickHomeActivity.this,"favorites",favorite);choose();}},"",null);back=new Runnable(){public void run(){home();}};}
 private void slots(){final int[] ids=AppCatalog.shortcuts(this);ArrayList<String> rows=new ArrayList<String>();for(int i=0;i<4;i++)rows.add((i+1)+" · "+AppCatalog.NAMES[ids[i]]);list("Scurtături Home",rows,0,new Choice(){public void pick(final int slot){options("Alege aplicația",AppCatalog.NAMES,new Choice(){public void pick(int id){getSharedPreferences("appearance",0).edit().putInt("shortcut"+slot,id).apply();slots();}});}},"",null);back=new Runnable(){public void run(){home();}};}
}
